SELECT AVG(icustays.los) AS average_los FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND patients.anchor_age = 74 AND EXTRACT(YEAR FROM admissions.admittime) BETWEEN 2019 AND 2020 AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = patients.subject_id AND diagnoses_icd.icd_code IN ('UGIB', 'COPD')) AND EXTRACT(YEAR FROM patients.anchor_year) BETWEEN 2019 AND 2020;